import { SVGLoader } from 'three/examples/jsm/loaders/SVGLoader.js';

const LOGO_PATH =
  'M 0 0 L 6 0 L 3 5 L 8 5 L 1 14 L 3 7 L 0 7 Z';

const SVG_DOCUMENT = `<svg xmlns="http://www.w3.org/2000/svg">
  <path d="${LOGO_PATH}"/>
</svg>`;

/**
 * Build the extruded 3D logo mesh.
 * @returns {THREE.Mesh} mesh with ExtrudeGeometry centered on its bounding box
 */
export function buildLogo() {
  const loader = new SVGLoader();
  const svgData = loader.parse(SVG_DOCUMENT);

  // Convert every path's sub-paths into THREE.Shape instances
  const shapes = [];
  for (const path of svgData.paths) {
    shapes.push(...SVGLoader.createShapes(path));
  }

  const geometry = new THREE.ExtrudeGeometry(shapes, {
    depth: 2,
    bevelEnabled: false,
  });

  // Center the geometry on its bounding box
  geometry.computeBoundingBox();
  const center = new THREE.Vector3();
  geometry.boundingBox.getCenter(center);
  geometry.translate(-center.x, -center.y, -center.z);
  geometry.computeBoundingBox();

  return new THREE.Mesh(geometry, new THREE.MeshBasicMaterial());
}

/**
 * Footprint (axis-aligned extents) of the logo mesh's bounding box,
 * measured after centering.
 * @returns {{width: number, height: number, depth: number}}
 */
export function logoFootprint() {
  const mesh = buildLogo();
  mesh.geometry.computeBoundingBox();
  const box = new THREE.Box3().setFromObject(mesh);
  const size = box.getSize(new THREE.Vector3());
  return { width: size.x, height: size.y, depth: size.z };
}
