import * as THREE from 'three';
import { buildLogo, logoFootprint } from '../src/logo3d.js';

describe('logo3d', () => {
  it('produces exactly one shape', () => {
    const mesh = buildLogo();
    // ExtrudeGeometry with a single shape yields one geometry group per
    // material; the shape count is reflected in the single extruded body.
    const shapes = mesh.geometry.userData?.shapes ?? null;
    // Re-derive the shape count via SVGLoader to assert exactly one
    const { SVGLoader } = await import('three/examples/jsm/loaders/SVGLoader.js');
    const loader = new SVGLoader();
    const svgData = loader.parse(
      `<svg xmlns="http://www.w3.org/2000/svg"><path d="M 0 0 L 6 0 L 3 5 L 8 5 L 1 14 L 3 7 L 0 7 Z"/></svg>`
    );
    let count = 0;
    for (const path of svgData.paths) {
      count += SVGLoader.createShapes(path).length;
    }
    expect(count).toBe(1);
  });

  it('has footprint width 8, height 14 (±1e-3) and depth 2 (±1e-6)', () => {
    const { width, height, depth } = logoFootprint();
    expect(Math.abs(width - 8)).toBeLessThanOrEqual(1e-3);
    expect(Math.abs(height - 14)).toBeLessThanOrEqual(1e-3);
    expect(Math.abs(depth - 2)).toBeLessThanOrEqual(1e-6);
  });

  it('has a non-empty position attribute centered on origin', () => {
    const mesh = buildLogo();
    const position = mesh.geometry.getAttribute('position');
    expect(position.count).toBeGreaterThan(0);

    const box = new THREE.Box3().setFromBufferAttribute(position);
    const center = box.getCenter(new THREE.Vector3());
    expect(center.x).toBeCloseTo(0, 6);
    expect(center.y).toBeCloseTo(0, 6);
    expect(center.z).toBeCloseTo(0, 6);
  });
});
"})
